import { useRef, useState } from "react";
import { motion, useInView, AnimatePresence } from "framer-motion";
import "./Villains.css";

const villains = [
  {
    name: "GREEN GOBLIN",
    alter: "Norman Osborn",
    threat: "EXTREME",
    color: "#39a839",
    accent: "#7fff7f",
    symbol: "🎃",
    desc: "Brilliant industrialist turned psychotic supervillain. Spider-Man's greatest nemesis — the man who shattered Peter Parker's world forever.",
    image: "data:image/jpeg;base64,",
    webColor: "rgba(57,168,57,0.4)",
  },
  {
    name: "DOC OCTOPUS",
    alter: "Otto Octavius",
    threat: "HIGH",
    color: "#c47a3a",
    accent: "#ffc078",
    symbol: "🐙",
    desc: "Genius physicist with four prehensile adamantium arms fused to his nervous system after a catastrophic lab explosion.",
    image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQk9ctKOIMm0e5_Vz8hljNuw93mY-CItOvpSQ&s",
    webColor: "rgba(196,122,58,0.4)",
  },
  {
    name: "VENOM",
    alter: "Eddie Brock",
    threat: "EXTREME",
    color: "#a0a0ff",
    accent: "#ffffff",
    symbol: "👾",
    desc: "A living alien symbiote bonded to embittered journalist Eddie Brock — Spider-Man's dark mirror with an insatiable hunger.",
    image: "data:image/jpeg;base64,",
    webColor: "rgba(80,80,180,0.4)",
  },
  {
    name: "ELECTRO",
    alter: "Maxwell Dillon",
    threat: "HIGH",
    color: "#f5c818",
    accent: "#fff176",
    symbol: "⚡",
    desc: "Former electrical engineer transformed into a living lightning battery capable of channeling unlimited voltage.",
    image: "data:image/jpeg;base64,",
    webColor: "rgba(245,200,24,0.4)",
  },
  {
    name: "VULTURE",
    alter: "Adrian Toomes",
    threat: "MED",
    color: "#5aaa5a",
    accent: "#a8f0a8",
    symbol: "🦅",
    desc: "Cunning elder criminal with engineered electromagnetic wings granting supersonic flight and razor-sharp predatory instinct.",
    image: "data:image/jpeg;base64,",
    webColor: "rgba(90,170,90,0.4)",
  },
  {
    name: "SANDMAN",
    alter: "Flint Marko",
    threat: "HIGH",
    color: "#d4a96a",
    accent: "#ffe0a0",
    symbol: "🏖️",
    desc: "His molecular structure is pure silica — impossible to contain and capable of devastating destructive force.",
    image: "data:image/jpeg;base64,",
    webColor: "rgba(212,169,106,0.4)",
  },
];

const FALLBACK = (name, color) =>
  `https://placehold.co/400x560/${color.replace("#", "")}1a/ffffff?text=${encodeURIComponent(name)}&font=bebas-neue`;

export default function Villains() {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-80px" });
  const [active, setActive] = useState(null);
  const [webBurst, setWebBurst] = useState(null);

  const handleCardClick = (i) => {
    setActive(active === i ? null : i);
    setWebBurst(i);
    setTimeout(() => setWebBurst(null), 700);
  };

  return (
    <section className="villains" id="villains" ref={ref}>
      {/* Animated web strands background */}
      <div className="villains-web-bg" aria-hidden="true">
        {[...Array(6)].map((_, i) => (
          <div key={i} className={`web-strand web-strand--${i + 1}`} />
        ))}
      </div>

      <div className="villains-header">
        <motion.p className="section-label" initial={{ opacity: 0, letterSpacing: "0.3em" }} animate={inView ? { opacity: 1, letterSpacing: "0.5em" } : {}} transition={{ duration: 1 }}>
          — Rogues Gallery —
        </motion.p>
        <motion.h2 className="section-title" initial={{ opacity: 0, y: 40 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ delay: 0.15, duration: 0.7 }}>
          THE <span className="text-red">ENEMIES</span>
        </motion.h2>
        <motion.div className="title-web-line" initial={{ scaleX: 0 }} animate={inView ? { scaleX: 1 } : {}} transition={{ delay: 0.4, duration: 0.8 }} />
      </div>

      <div className="villains-grid">
        {villains.map((v, i) => (
          <motion.div
            key={v.name}
            className={`villain-card ${active === i ? "active" : ""}`}
            style={{ "--v-color": v.color, "--v-accent": v.accent, "--v-web": v.webColor }}
            initial={{ opacity: 0, y: 50, scale: 0.95 }}
            animate={inView ? { opacity: 1, y: 0, scale: 1 } : {}}
            transition={{ delay: i * 0.1, duration: 0.6, ease: "easeOut" }}
            onClick={() => handleCardClick(i)}
          >
            {/* Image */}
            <div className="vc-img-wrap">
              <img
                src={v.image}
                alt={v.name}
                className="vc-img"
                loading="lazy"
                onError={(e) => { e.target.onerror = null; e.target.src = FALLBACK(v.name, v.color); }}
              />
              <div className="vc-img-scanline" />
            </div>

            {/* Color tint overlay */}
            <div className="vc-tint" />

            {/* Web burst on click */}
            <AnimatePresence>
              {webBurst === i && (
                <motion.div className="vc-web-burst" initial={{ scale: 0, opacity: 0.9 }} animate={{ scale: 3, opacity: 0 }} exit={{}} transition={{ duration: 0.6, ease: "easeOut" }} style={{ background: `radial-gradient(circle, ${v.webColor} 0%, transparent 70%)` }} />
              )}
            </AnimatePresence>

            {/* Spider-web corner */}
            <div className="vc-web-corner" />

            {/* Threat badge */}
            <div className="vc-threat" data-level={v.threat}>{v.threat}</div>

            {/* Content */}
            <div className="vc-content">
              <div className="vc-symbol">{v.symbol}</div>
              <h3 className="vc-name">{v.name}</h3>
              <p className="vc-alter">// {v.alter}</p>
              <AnimatePresence>
                {active === i && (
                  <motion.p className="vc-desc" initial={{ opacity: 0, height: 0, marginTop: 0 }} animate={{ opacity: 1, height: "auto", marginTop: "0.9rem" }} exit={{ opacity: 0, height: 0, marginTop: 0 }} transition={{ duration: 0.35 }}>
                    {v.desc}
                  </motion.p>
                )}
              </AnimatePresence>
            </div>

            {/* Expand toggle */}
            <motion.div className="vc-expand" animate={{ rotate: active === i ? 45 : 0 }} transition={{ duration: 0.3 }}>+</motion.div>

            {/* Bottom web line */}
            <div className="vc-bottom-line" />
          </motion.div>
        ))}
      </div>

      <motion.div className="villains-cta" initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}} transition={{ delay: 0.7 }}>
        <p>Every villain forged a stronger Spider-Man.</p>
        <button className="btn-primary" onClick={() => window.open("https://www.marvel.com/characters/spider-man-peter-parker/in-comics", "_blank")}>
          <span className="btn-web-left">◈</span>
          SEE ALL VILLAINS
          <span className="btn-web-right">◈</span>
        </button>
      </motion.div>
    </section>
  );
}